def build_instance(rng):
    number_count = rng.randint(4, 12)
    average_value = rng.randint(15, 60)
    correction_steps = rng.randint(-3, 5)
    if correction_steps == 0:
        correction_steps = 2
    recorded_number = average_value
    corrected_number = recorded_number + number_count * correction_steps
    answer = average_value + correction_steps
    measurements = [average_value] * number_count
    measurements[-1] = corrected_number
    check = sum(measurements) // number_count
    assert answer == check, f'answer={answer} check={check}'
    parameters = {'number_count': number_count, 'average_value': average_value, 'recorded_number': recorded_number, 'corrected_number': corrected_number}
    return (parameters, answer, check)



