import sympy
import fractions

def build_instance(rng):
    value_at_zero = rng.randint(-9, 9)
    value_at_one = rng.randint(-9, 9)
    value_at_two = rng.randint(-9, 9)
    x = sympy.symbols('x')
    f = sympy.Poly([value_at_zero, value_at_one - value_at_zero, value_at_two - 2 * value_at_one + value_at_zero], x)
    answer = f.coeffs()[0] * 3 ** 2 + f.coeffs()[1] * 3 + f.coeffs()[2]
    check = f.subs(x, 3)
    parameters = {'value_at_zero': value_at_zero, 'value_at_one': value_at_one, 'value_at_two': value_at_two}
    return (parameters, answer, check)



