    root1 = rng.randint(-5, 5)
    root2 = rng.randint(-5, 5)
    root3 = rng.randint(-5, 5)
    incorrect_root1 = rng.randint(-10, 10)
    corrected_root1 = rng.randint(-10, 10)
    if incorrect_root1 == corrected_root1:
        corrected_root1 = rng.randint(-10, 10)
    direct_value = fractions.Fraction(degree * (root1 + root2 + root3), 1) - fractions.Fraction(degree * (incorrect_root1 - corrected_root1), 1)
    answer = str(direct_value)
    x = sympy.symbols('x')
    polynomial = sympy.Poly(x ** degree + (root1 + root2 + root3) * x ** (degree - 1) + (root1 * root2 + root1 * root3 + root2 * root3) * x ** (degree - 2) + root1 * root2 * root3 * x ** (degree - 3), x)
    corrected_polynomial = sympy.Poly(x ** degree + (root1 + root2 + corrected_root1) * x ** (degree - 1) + (root1 * root2 + root1 * corrected_root1 + root2 * corrected_root1) * x ** (degree - 2) + root1 * root2 * corrected_root1 * x ** (degree - 3), x)
    symbolic_value = corrected_polynomial.coeff_monomial(x ** (degree - 1))
