import random

def build_instance(rng):
    vertex_count = rng.randint(3, 6)
    vertex_degree = rng.randint(1, vertex_count - 1)
    edges = list(itertools.combinations(range(vertex_count), 2))
    adjacency_matrix = [[0] * vertex_count for _ in range(vertex_count)]
    for i in range(vertex_count):
        for j in range(i + 1, vertex_count):
            if adjacency_matrix[i][j] == 0:
                adjacency_matrix[i][j] = 1
                adjacency_matrix[j][i] = 1
                if sum(adjacency_matrix[i]) == vertex_degree and sum(adjacency_matrix[j]) == vertex_degree:
                    break
    else:
        return None
    triangle_free = all((not {(i, j), (i, k), (j, k)} <= set((i, j) for i, j in edges) for i, j, k in itertools.combinations(range(vertex_count), 3)))
    answer = triangle_free
    check = all((sum(adjacency_matrix[i]) == vertex_degree for i in range(vertex_count)))
    parameters = {"vertex_count": vertex_count, "vertex_degree": vertex_degree}
    return parameters, answer, check
