                if __rq_type(key) is not str or not key or __rq_len(key) > 128:
                    raise ValueError("stage2 payload dict keys must be short strings")
                __rq_validate_plain(item, depth=depth + 1, seen=seen, budget=budget)
        else:
            for item in value:
                __rq_validate_plain(item, depth=depth + 1, seen=seen, budget=budget)
