import sympy

def build_instance(rng):
    coefficient = rng.randint(1, 5)
    constant = rng.randint(1, 5)
    discriminant = coefficient ** 2 - 4 * constant
    answer = discriminant
    check = int(sympy.discriminant(sympy.symbols('x') ** 2 - coefficient * sympy.symbols('x') + constant))
    parameters = {'coefficient': coefficient, 'constant': constant}
    return (parameters, answer, check)



